#include <Arduino.h>
#include <ArduinoJson.h>
#include <WiFi.h>
#include <ArduinoMqttClient.h>
#include <WiFiClientSecure.h>
#include <time.h>
#include <sys/time.h>
#include <LittleFS.h>
#include "config.h"
#include "event_buffer.h"
#include "watchdog.h"
#include "laser_sensor.h"
EventBuffer buffer;WiFiClientSecure tls;MqttClient mqtt(tls);QueueHandle_t q;uint32_t seq=0;volatile bool time_synced=false;LaserSensor laser;
static bool wifi(){WiFi.mode(WIFI_STA);WiFi.begin(WIFI_SSID,WIFI_PASSWORD);uint32_t t=millis();while(WiFi.status()!=WL_CONNECTED&&millis()-t<10000)vTaskDelay(pdMS_TO_TICKS(250));if(WiFi.status()==WL_CONNECTED){configTime(0,0,"pool.ntp.org","time.nist.gov");time_t now=0;uint32_t start=millis();while(now<1700000000 && millis()-start<10000){time(&now);vTaskDelay(pdMS_TO_TICKS(250));}time_synced=now>=1700000000;}return WiFi.status()==WL_CONNECTED;}
static bool connect_mqtt(){if(!LittleFS.begin(true))return false;File ca=LittleFS.open("/mqtt_ca.pem","r");if(!ca)return false;String pem=ca.readString();ca.close();if(pem.length()<64)return false;tls.setCACert(pem.c_str());mqtt.setId(DEVICE_ID);mqtt.setUsernamePassword(MQTT_USER,MQTT_PASSWORD);mqtt.subscribe("events/ack",1);if(mqtt.connect(MQTT_PRIMARY_HOST,MQTT_PORT))return true;return mqtt.connect(MQTT_SECONDARY_HOST,MQTT_PORT);}
void sensor(void*){pinMode(PIN_SENSOR_PIR,INPUT);pinMode(PIN_SENSOR_DOOR,INPUT_PULLUP);pinMode(PIN_TAMPER,INPUT_PULLUP);laser.begin(PIN_SENSOR_LASER);for(;;){watchdog_kick_sensor();bool m=digitalRead(PIN_SENSOR_PIR),d=digitalRead(PIN_SENSOR_DOOR)==LOW,t=digitalRead(PIN_TAMPER)==LOW,l=laser.justTripped();if(m||d||t||l){SecurityEvent e={};uint32_t r1=esp_random(),r2=esp_random(),r3=esp_random(),r4=esp_random();snprintf(e.event_id,sizeof(e.event_id),"%08lx-%04lx-%04lx-%04lx-%012lx",(unsigned long)r1,(unsigned long)(r2&0xffff),(unsigned long)((r3&0x0fff)|0x4000),(unsigned long)((r4&0x3fff)|0x8000),(unsigned long)(((uint64_t)esp_random()<<16)|((uint64_t)esp_random()&0xffff)));e.sequence_number=++seq;e.timestamp=(uint64_t)time(nullptr)*1000ULL;strcpy(e.type,l?"LASER_TRIPWIRE":t?"TAMPER":d?"DOOR":"MOTION");strcpy(e.priority,(t||l)?"CRITICAL":"SECURITY");snprintf(e.payload,sizeof(e.payload),"{\"motion\":%d,\"door\":%d,\"tamper\":%d,\"laser\":%d}",m,d,t,l);xQueueSend(q,&e,pdMS_TO_TICKS(200));}vTaskDelay(pdMS_TO_TICKS(200));}}
void storage(void*){SecurityEvent e;for(;;){watchdog_kick_store();if(xQueueReceive(q,&e,pdMS_TO_TICKS(500))==pdTRUE)buffer.push(e);vTaskDelay(pdMS_TO_TICKS(50));}}
void network(void*){for(;;){watchdog_kick_net();if(WiFi.status()!=WL_CONNECTED)wifi();if(!mqtt.connected())connect_mqtt();if(mqtt.connected()){mqtt.poll();SecurityEvent e;if(buffer.peek(e)){StaticJsonDocument<768>d;d["event_id"]=e.event_id;d["device_id"]=DEVICE_ID;d["zone"]=ZONE_ID;d["sequence_number"]=e.sequence_number;d["timestamp"]=e.timestamp;d["type"]=e.type;d["priority"]=e.priority;JsonObject p=d["payload"].to<JsonObject>();StaticJsonDocument<256>tmp;deserializeJson(tmp,e.payload);p.set(tmp.as<JsonVariant>());String out;serializeJson(d,out);mqtt.beginMessage("events/ingest",out.length(),false,1,false);mqtt.print(out);mqtt.endMessage();uint32_t t=millis();while(millis()-t<3000){mqtt.poll();if(mqtt.parseMessage()){StaticJsonDocument<256>a;String s;while(mqtt.available())s+=(char)mqtt.read();if(deserializeJson(a,s)==DeserializationError::Ok&&strcmp(a["event_id"]|"",e.event_id)==0){const char*st=a["status"]|"";if(strcmp(st,"OK")==0||strcmp(st,"DUPLICATE")==0||strcmp(st,"BUFFERED")==0||strcmp(st,"REJECTED")==0){buffer.ack(e.event_id);break;}}}vTaskDelay(pdMS_TO_TICKS(50));}}}vTaskDelay(pdMS_TO_TICKS(100));}}
void setup(){Serial.begin(115200);buffer.begin();q=xQueueCreate(QUEUE_LENGTH,sizeof(SecurityEvent));watchdog_init();xTaskCreatePinnedToCore(sensor,"sensor",TASK_STACK_SENSOR,nullptr,3,nullptr,1);xTaskCreatePinnedToCore(storage,"storage",TASK_STACK_STORE,nullptr,2,nullptr,1);xTaskCreatePinnedToCore(network,"network",TASK_STACK_NET,nullptr,2,nullptr,0);}void loop(){watchdog_feed();watchdog_supervise();vTaskDelay(pdMS_TO_TICKS(1000));}
